#include <algorithm>
#include <cassert>
#include <climits>
#include <functional>
#include <iostream>
#include <queue>
#include <stdexcept>
#include <vector>
using namespace std;
static_assert(INT_MIN==(-2147483647-1)&&INT_MAX==2147483647,"32-bit int required");
struct Rational{long long numerator;int denominator;};
class Median{
 priority_queue<int> lower;
 priority_queue<int,vector<int>,greater<int>> upper;
public:
 void add(int x){
  // 낮은 절반은 최대 힙, 높은 절반은 최소 힙입니다.
  if(lower.empty()||x<=lower.top())lower.push(x);else upper.push(x);
  if(lower.size()>upper.size()+1){upper.push(lower.top());lower.pop();}
  else if(upper.size()>lower.size()){lower.push(upper.top());upper.pop();}
 }
 Rational value()const{
  if(lower.empty())throw invalid_argument("empty stream");
  if(lower.size()>upper.size())return {lower.top(),1};
  // int에서 먼저 더하지 않고 넓힌 뒤 더하여 정확한 분자로 보관합니다.
  return {static_cast<long long>(lower.top())+upper.top(),2};
 }
};
int main(){
 size_t streams=0,prefixes=0;vector<vector<int>>level(1);
 for(int n=0;n<=6;++n){
  for(const auto&v:level){Median m;vector<int>sorted;
   for(int x:v){m.add(x);sorted.push_back(x);sort(sorted.begin(),sorted.end());
    size_t k=sorted.size();Rational expected=k%2?Rational{sorted[k/2],1}:Rational{static_cast<long long>(sorted[k/2-1])+sorted[k/2],2};
    Rational actual=m.value();assert(actual.numerator*expected.denominator==expected.numerator*actual.denominator);++prefixes;
   }++streams;
  }
  vector<vector<int>>next;for(const auto&v:level)for(int x:{-2,-1,0,1,2}){auto w=v;w.push_back(x);next.push_back(w);}level=next;
 }
 Median empty;bool bad=false;try{empty.value();}catch(const invalid_argument&){bad=true;}assert(bad);
 Median edge;edge.add(INT_MIN);edge.add(INT_MAX);assert(edge.value().numerator==-1&&edge.value().denominator==2);
 Median repeated;for(int i=0;i<100000;++i)repeated.add(INT_MAX);
 assert(repeated.value().numerator==4294967294LL&&repeated.value().denominator==2);
 cout<<streams<<" streams / "<<prefixes<<" prefixes + empty/int boundary cases passed\n";
}
